INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4a385a8b-0b07-57d9-ab64-e8691aa4f5c4', 'Slovakia Act Coll. on the collection, storage and dissemination', 'Act no. 205/2004 Coll. on the collection, storage and dissemination of information on the environment and on the amendment of certain laws', 'This document is concerned with the law of December 2, 2009, amending Act No. 205/2004 Coll. on collection, storage and dissemination of information about the environment and about changes and additions to certain laws as amended.', 'This document is concerned with the law of December 2, 2009, amending Act No. 205/2004 Coll. on collection, storage and dissemination of information about the environment and about changes and additions to certain laws as amended.', 'This document is concerned with the law of December 2, 2009, amending Act No. 205/2004 Coll. on collection, storage and dissemination of information about the environment and about changes and additions to certain laws as amended.', 'Slovakia', 'governance', 'in_force', '2009-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_7', ARRAY['slovakia', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ba1422c8-60ca-5abd-b3af-bc41d049fa9b', 'Corporate Governance Code for Slovakia', 'Corporate Governance Code for Slovakia, 2008', 'The Corporate Governance Code for Slovakia (hereinafter the ‘Code’) is a part of the Stock Exchange rules for securities admission to the regulated market, which are approved by the BSSE Management Board and the National Bank of Slovakia. In compliance with an Amendment to the Accountancy Act No 431/2002 Coll. as amended by subsequent legislation, effective from 1 January 2008, the Code applies to all companies that have securities admitted to trading on the BSSE’s regulated market i.e. on the Main Listed Market, the Parallel Listed Market and/or the Regulated Free Market. In their Annual Reports, for the year 2007 for the first time, said companies will include a statement prepared on the ‘comply or explain’ basis specifying to what degree they have complied with the principles of good corporate governance. If a company has not so far applied a certain principle, it will give reasons in the Annual Report.', 'The Corporate Governance Code for Slovakia (hereinafter the ‘Code’) is a part of the Stock Exchange rules for securities admission to the regulated market, which are approved by the BSSE Management Board and the National Bank of Slovakia. In compliance with an Amendment to the Accountancy Act No 431/2002 Coll. as amended by subsequent legislation, effective from 1 January 2008, the Code applies to all companies that have securities admitted to trading on the BSSE’s regulated market i.e. on the Main Listed Market, the Parallel Listed Market and/or the Regulated Free Market. In their Annual Reports, for the year 2007 for the first time, said companies will include a statement prepared on the ‘comply or explain’ basis specifying to what degree they have complied with the principles of good corporate governance. If a company has not so far applied a certain principle, it will give reasons in the Annual Report.', 'The Corporate Governance Code for Slovakia (hereinafter the ‘Code’) is a part of the Stock Exchange rules for securities admission to the regulated market, which are approved by the BSSE Management Board and the National Bank of Slovakia. In compliance with an Amendment to the Accountancy Act No 431/2002 Coll. as amended by subsequent legislation, effective from 1 January 2008, the Code applies to all companies that have securities admitted to trading on the BSSE’s regulated market i.e. on the Main Listed Market, the Parallel Listed Market and/or the Regulated Free Market. In their Annual Reports, for the year 2007 for the first time, said companies will include a statement prepared on the ‘comply or explain’ basis specifying to what degree they have complied with the principles of good corporate governance. If a company has not so far applied a certain principle, it will give reasons in the Annual Report.', 'Slovakia', 'climate', 'in_force', '2008-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_1', ARRAY['regulations', 'slovakia', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c7337260-43b2-5994-97ba-f4e3a513234c', 'Slovakia 348 Act of 28 June 2007 amending Act', '348 Act of 28 June 2007 amending Act no. 311/2001 Coll. Labor Code as amended and amending certain laws', 'This Act shall govern individual labour-law relations in connection with the performance of dependent work by natural persons for legal persons or natural persons and collective labour-law relations.', 'This Act shall govern individual labour-law relations in connection with the performance of dependent work by natural persons for legal persons or natural persons and collective labour-law relations.', 'This Act shall govern individual labour-law relations in connection with the performance of dependent work by natural persons for legal persons or natural persons and collective labour-law relations.', 'Slovakia', 'social', 'in_force', '2007-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_6', ARRAY['sdg8', 'regulations', 'slovakia', 'mandatory', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('abae34a9-1827-5ccb-bf4a-8c0b7b683690', 'Slovakia Corporate Governance Code (Based on the OECD Principles)', 'Corporate Governance Code (Based on the OECD Principles), 2002', 'The Code has been designed to set out the best practice for companies in the Slovak Republic. Focus is placed on openness, integrity and accountability as these elements are essential to encourage investor confidence. Therefore, the emphasis is on encouraging companies to sign up to the Code, adopt some of the provisions now and to explain to shareholders in the annual report why they are not adopting other provisions together with a date when they anticipate being able to do so. It is hoped that companies will be able to progressively implement those provisions of the Code which they are not able to implement immediately leading to full compliance within the next few years.', 'The Code has been designed to set out the best practice for companies in the Slovak Republic. Focus is placed on openness, integrity and accountability as these elements are essential to encourage investor confidence. Therefore, the emphasis is on encouraging companies to sign up to the Code, adopt some of the provisions now and to explain to shareholders in the annual report why they are not adopting other provisions together with a date when they anticipate being able to do so. It is hoped that companies will be able to progressively implement those provisions of the Code which they are not able to implement immediately leading to full compliance within the next few years.', 'The Code has been designed to set out the best practice for companies in the Slovak Republic. Focus is placed on openness, integrity and accountability as these elements are essential to encourage investor confidence. Therefore, the emphasis is on encouraging companies to sign up to the Code, adopt some of the provisions now and to explain to shareholders in the annual report why they are not adopting other provisions together with a date when they anticipate being able to do so. It is hoped that companies will be able to progressively implement those provisions of the Code which they are not able to implement immediately leading to full compliance within the next few years.', 'Slovakia', 'climate', 'in_force', '2002-01-01'::date, 'Slovakia', 'https://www.carrotsandsticks.org/policies/162_4', ARRAY['guidance_frameworks', 'slovakia', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('aa6b2c46-747e-5409-a0d3-abbee371ea4e', 'Slovenia Amendments to the Financial Instruments Market Act (ZTFI-1D)', 'Act on Amendments to the Financial Instruments Market Act (ZTFI-1D)', 'The Act on Amendments to the Financial Instruments Market Act (ZTFI-1D) in Slovenia updates regulations to align with EU directives, focusing on improving settlement of securities and access to financial information. It targets financial institutions, investors, and regulators to enhance market efficiency and transparency.', 'The Act on Amendments to the Financial Instruments Market Act (ZTFI-1D) in Slovenia updates regulations to align with EU directives, focusing on improving settlement of securities and access to financial information. It targets financial institutions, investors, and regulators to enhance market efficiency and transparency.', 'The Act on Amendments to the Financial Instruments Market Act (ZTFI-1D) in Slovenia updates regulations to align with EU directives, focusing on improving settlement of securities and access to financial information. It targets financial institutions, investors, and regulators to enhance market efficiency and transparency.', 'Slovenia', 'governance', 'in_force', '2025-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_12', ARRAY['sdg16', 'slovenia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6415c624-8142-5b38-8d13-addda5399eda', 'Slovenia 2264. Climate Act (PoZ)', '2264. Climate Act (PoZ)', 'The 2264 Climate Act (PoZ) in Slovenia, enacted in 2025, aims to address climate change through strategies, emission reduction measures, trading systems, monitoring, and financial instruments. It aligns with EU directives on emissions trading and CO2 information for consumers, targeting operators, businesses, and regulated entities.', 'The 2264 Climate Act (PoZ) in Slovenia, enacted in 2025, aims to address climate change through strategies, emission reduction measures, trading systems, monitoring, and financial instruments. It aligns with EU directives on emissions trading and CO2 information for consumers, targeting operators, businesses, and regulated entities.', 'The 2264 Climate Act (PoZ) in Slovenia, enacted in 2025, aims to address climate change through strategies, emission reduction measures, trading systems, monitoring, and financial instruments. It aligns with EU directives on emissions trading and CO2 information for consumers, targeting operators, businesses, and regulated entities.', 'Slovenia', 'climate', 'in_force', '2025-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_13', ARRAY['slovenia', 'mandatory', 'sdg13', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c7384a76-8f23-549c-82fb-f79898256165', 'Slovenia Act amending the Act amending and supplementing the', 'Act amending the Act amending and supplementing the Companies Act (ZGD-1N)', 'The Act amending the Companies Act (ZGD-1N) updates specific deadlines within the existing legislation, extending the timeline for certain provisions from 2025 to 2027 and from 2026 to 2028. This amendment applies to all companies operating under the Companies Act in Slovenia, ensuring compliance with the revised timelines. The law becomes effective the day after its publication in the Official Gazette of the Republic of Slovenia.', 'The Act amending the Companies Act (ZGD-1N) updates specific deadlines within the existing legislation, extending the timeline for certain provisions from 2025 to 2027 and from 2026 to 2028. This amendment applies to all companies operating under the Companies Act in Slovenia, ensuring compliance with the revised timelines. The law becomes effective the day after its publication in the Official Gazette of the Republic of Slovenia.', 'The Act amending the Companies Act (ZGD-1N) updates specific deadlines within the existing legislation, extending the timeline for certain provisions from 2025 to 2027 and from 2026 to 2028. This amendment applies to all companies operating under the Companies Act in Slovenia, ensuring compliance with the revised timelines. The law becomes effective the day after its publication in the Official Gazette of the Republic of Slovenia.', 'Slovenia', 'governance', 'in_force', '2025-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_14', ARRAY['slovenia', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1301a2a6-5e30-5dc6-96b6-54447c6b3a4b', 'Slovenia Amendments to the Companies Act (ZGD-1M)', 'Act on Amendments to the Companies Act (ZGD-1M)', 'The Act on Amendments to the Companies Act (ZGD-1M) in Slovenia, effective from October 8, 2025, aligns national laws with EU directives on shareholder rights, corporate governance, and financial reporting. It impacts companies, shareholders, and regulatory bodies by enhancing transparency and compliance with EU standards.', 'The Act on Amendments to the Companies Act (ZGD-1M) in Slovenia, effective from October 8, 2025, aligns national laws with EU directives on shareholder rights, corporate governance, and financial reporting. It impacts companies, shareholders, and regulatory bodies by enhancing transparency and compliance with EU standards.', 'The Act on Amendments to the Companies Act (ZGD-1M) in Slovenia, effective from October 8, 2025, aligns national laws with EU directives on shareholder rights, corporate governance, and financial reporting. It impacts companies, shareholders, and regulatory bodies by enhancing transparency and compliance with EU standards.', 'Slovenia', 'climate', 'in_force', '2024-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_10', ARRAY['sdg16', 'slovenia', 'mandatory', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a78cf077-0b3a-5c73-88c0-ee9344aaff24', 'Slovenia Amendments to the Auditing Act (ZRev-2C)', 'Act on Amendments to the Auditing Act (ZRev-2C)', 'The Act on Amendments to the Auditing Act (ZRev-2C) in Slovenia outlines regulations for auditing financial statements, sustainability assurance, and agreed-upon procedures. It incorporates EU directives on mandatory audits and aims to enhance oversight of auditing practices, focusing on public interest entities and audit firms.', 'The Act on Amendments to the Auditing Act (ZRev-2C) in Slovenia outlines regulations for auditing financial statements, sustainability assurance, and agreed-upon procedures. It incorporates EU directives on mandatory audits and aims to enhance oversight of auditing practices, focusing on public interest entities and audit firms.', 'The Act on Amendments to the Auditing Act (ZRev-2C) in Slovenia outlines regulations for auditing financial statements, sustainability assurance, and agreed-upon procedures. It incorporates EU directives on mandatory audits and aims to enhance oversight of auditing practices, focusing on public interest entities and audit firms.', 'Slovenia', 'climate', 'in_force', '2024-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_11', ARRAY['sdg13', 'regulations', 'slovenia', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ec5317c-d977-5fd8-97fe-ce32e9133f10', 'Slovenian Corporate Governane Code for Listed Companies', 'Slovenian Corporate Governane Code for Listed Companies, 2021', 'A revised version of the Slovenian Corporate Governance Code for Listed Companies jointly drawn up and adopted by the Ljubljana Stock Exchange and the Slovenian Directors’ Association. The present version of the Code is the sixth amendment to the first Code from 2004.', 'A revised version of the Slovenian Corporate Governance Code for Listed Companies jointly drawn up and adopted by the Ljubljana Stock Exchange and the Slovenian Directors’ Association. The present version of the Code is the sixth amendment to the first Code from 2004.', 'A revised version of the Slovenian Corporate Governance Code for Listed Companies jointly drawn up and adopted by the Ljubljana Stock Exchange and the Slovenian Directors’ Association. The present version of the Code is the sixth amendment to the first Code from 2004.', 'Slovenia', 'governance', 'in_force', '2021-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_9', ARRAY['slovenia', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d494544c-2139-533f-9901-f8c4d9bf469f', 'Slovenia Slovene Corporate Governance Code For Listed Companies', 'Slovene Corporate Governance Code For Listed Companies, 2016', 'The Slovene Corporate Governance Code for Listed Companies was jointly drawn up and adopted by the Ljubljana Stock Exchange Inc., the Slovenian Directors’ Association and the Managers'' Association of Slovenia on 18 March 2004. They agreed to amend and supplement it on 14 December 2005, 5 February 2007 and 8 December 2009.The Code in its current wording was drawn up and adopted by the Ljubljana Stock Exchange Inc. and the Slovenian Directors’ Association on 27 October 2016.This is an English translation of the Code; in case of discrepancies between the translation and the original Slovene version, the Slovene version shall prevail.', 'The Slovene Corporate Governance Code for Listed Companies was jointly drawn up and adopted by the Ljubljana Stock Exchange Inc., the Slovenian Directors’ Association and the Managers'' Association of Slovenia on 18 March 2004. They agreed to amend and supplement it on 14 December 2005, 5 February 2007 and 8 December 2009.The Code in its current wording was drawn up and adopted by the Ljubljana Stock Exchange Inc. and the Slovenian Directors’ Association on 27 October 2016.This is an English translation of the Code; in case of discrepancies between the translation and the original Slovene version, the Slovene version shall prevail.', 'The Slovene Corporate Governance Code for Listed Companies was jointly drawn up and adopted by the Ljubljana Stock Exchange Inc., the Slovenian Directors’ Association and the Managers'' Association of Slovenia on 18 March 2004. They agreed to amend and supplement it on 14 December 2005, 5 February 2007 and 8 December 2009.The Code in its current wording was drawn up and adopted by the Ljubljana Stock Exchange Inc. and the Slovenian Directors’ Association on 27 October 2016.This is an English translation of the Code; in case of discrepancies between the translation and the original Slovene version, the Slovene version shall prevail.', 'Slovenia', 'governance', 'in_force', '2016-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_6', ARRAY['slovenia', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('31ed911a-d2ea-5189-be1d-226d3cc02922', 'Slovenia Corporate Governance Code for Unlisted Companies, 2106', 'The Corporate Governance Code for Unlisted Companies, 2106', 'The Code primarily represents an opportunity for audited companies (usually medium and large companies) that are not listed on the stock exchange to increase or improve their funding opportunities and investment potential. Good corporate governance in the financing of these companies is followed by banks and other financial institutions, which are aware that sound corporate governance is one of the competitive advantages of an individual company, which allows it to achieve better financing conditions and better manage risks.', 'The Code primarily represents an opportunity for audited companies (usually medium and large companies) that are not listed on the stock exchange to increase or improve their funding opportunities and investment potential. Good corporate governance in the financing of these companies is followed by banks and other financial institutions, which are aware that sound corporate governance is one of the competitive advantages of an individual company, which allows it to achieve better financing conditions and better manage risks.', 'The Code primarily represents an opportunity for audited companies (usually medium and large companies) that are not listed on the stock exchange to increase or improve their funding opportunities and investment potential. Good corporate governance in the financing of these companies is followed by banks and other financial institutions, which are aware that sound corporate governance is one of the competitive advantages of an individual company, which allows it to achieve better financing conditions and better manage risks.', 'Slovenia', 'climate', 'in_force', '2016-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_7', ARRAY['slovenia', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('882502c1-2e2a-55d7-89b3-345bfd1ce243', 'Slovenia regional aid map for the period', 'Regulation on the regional aid map for the period 2014-2021', 'This Regulation determines the areas in the Republic of Slovenia eligible for regional aid and the intensity of regional aid in individual eligible areas. The regional aid map is a list of eligible areas for granting of related regional aid. Regional aid is a type of State aid aimed to promote the economic development of areas in the European Union which are compatible with the EU internal market pursuant to article 107 (3) (a) (c) of the Treaty on the Functioning of the European Union. This type of aimed in meant for areas with extremely unfavorable economic conditions compared to the EU as a whole, and for areas where economic situation is unfavorable.', 'This Regulation determines the areas in the Republic of Slovenia eligible for regional aid and the intensity of regional aid in individual eligible areas. The regional aid map is a list of eligible areas for granting of related regional aid. Regional aid is a type of State aid aimed to promote the economic development of areas in the European Union which are compatible with the EU internal market pursuant to article 107 (3) (a) (c) of the Treaty on the Functioning of the European Union. This type of aimed in meant for areas with extremely unfavorable economic conditions compared to the EU as a whole, and for areas where economic situation is unfavorable.', 'This Regulation determines the areas in the Republic of Slovenia eligible for regional aid and the intensity of regional aid in individual eligible areas. The regional aid map is a list of eligible areas for granting of related regional aid. Regional aid is a type of State aid aimed to promote the economic development of areas in the European Union which are compatible with the EU internal market pursuant to article 107 (3) (a) (c) of the Treaty on the Functioning of the European Union. This type of aimed in meant for areas with extremely unfavorable economic conditions compared to the EU as a whole, and for areas where economic situation is unfavorable.', 'Slovenia', 'governance', 'in_force', '2013-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_1', ARRAY['slovenia', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6ff7a2d8-45a3-5569-89d3-11d326eec1ad', 'Slovenia Corporate Governance Code', 'Corporate Governance Code, 2009', 'The purpose of the Code is to define the governance and management principles of companies listed on the Slovene regulated market. The recommended practices can also be applied by other companies, so as to contribute to a transparent and understandable governance system in Slovenia, which promotes both domestic and foreign investor confidence into the Slovene corporate governance system, as well as the confidence of employees and the general public.', 'The purpose of the Code is to define the governance and management principles of companies listed on the Slovene regulated market. The recommended practices can also be applied by other companies, so as to contribute to a transparent and understandable governance system in Slovenia, which promotes both domestic and foreign investor confidence into the Slovene corporate governance system, as well as the confidence of employees and the general public.', 'The purpose of the Code is to define the governance and management principles of companies listed on the Slovene regulated market. The recommended practices can also be applied by other companies, so as to contribute to a transparent and understandable governance system in Slovenia, which promotes both domestic and foreign investor confidence into the Slovene corporate governance system, as well as the confidence of employees and the general public.', 'Slovenia', 'governance', 'in_force', '2009-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_5', ARRAY['regulations', 'slovenia', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8fb36ab7-3caf-5850-9d07-edb380e5ca25', 'Slovenia Corporate Governance Code (Amended 5 February', 'Corporate Governance Code (Amended 5 February 2007)', 'The Corporate Governance Code for Joint Stock Companies was jointly phrased and adopted by the Ljubljana Stock Exchange, Inc., Ljubljana, the Association of Supervisory Board Members of Slovenia, and the Managers'' Association of Slovenia on 18 March 2004, agreeing on adopting its amendments on 14 December 2005 and 5 February 2007.', 'The Corporate Governance Code for Joint Stock Companies was jointly phrased and adopted by the Ljubljana Stock Exchange, Inc., Ljubljana, the Association of Supervisory Board Members of Slovenia, and the Managers'' Association of Slovenia on 18 March 2004, agreeing on adopting its amendments on 14 December 2005 and 5 February 2007.', 'The Corporate Governance Code for Joint Stock Companies was jointly phrased and adopted by the Ljubljana Stock Exchange, Inc., Ljubljana, the Association of Supervisory Board Members of Slovenia, and the Managers'' Association of Slovenia on 18 March 2004, agreeing on adopting its amendments on 14 December 2005 and 5 February 2007.', 'Slovenia', 'governance', 'in_force', '2007-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_2', ARRAY['slovenia', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4adfc5e8-2f08-518f-a0f7-463ffd820034', 'Slovenia Corporate Governance Code', 'Corporate Governance Code, 2005', 'The purpose of the Code is to define in more detail the principles of directing and managing public joint-stock companies, whose shares are listed on the regulated market. The recommended practices should be applied also by other public and non-public companies, so that a transparent and understandable governance system is set up in Slovenia, which will promote the confidence of domestic and foreign investors, of employees and the general public in the Slovene two-tier system of governing public companies. The Code''s provisions summarise the relevant laws, indicate recommended conduct practices for public companies'' bodies and bridge the gap between their existing and the future legal regulation.', 'The purpose of the Code is to define in more detail the principles of directing and managing public joint-stock companies, whose shares are listed on the regulated market. The recommended practices should be applied also by other public and non-public companies, so that a transparent and understandable governance system is set up in Slovenia, which will promote the confidence of domestic and foreign investors, of employees and the general public in the Slovene two-tier system of governing public companies. The Code''s provisions summarise the relevant laws, indicate recommended conduct practices for public companies'' bodies and bridge the gap between their existing and the future legal regulation.', 'The purpose of the Code is to define in more detail the principles of directing and managing public joint-stock companies, whose shares are listed on the regulated market. The recommended practices should be applied also by other public and non-public companies, so that a transparent and understandable governance system is set up in Slovenia, which will promote the confidence of domestic and foreign investors, of employees and the general public in the Slovene two-tier system of governing public companies. The Code''s provisions summarise the relevant laws, indicate recommended conduct practices for public companies'' bodies and bridge the gap between their existing and the future legal regulation.', 'Slovenia', 'governance', 'in_force', '2005-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_4', ARRAY['other sustainability policy', 'regulations', 'slovenia', 'mandatory', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('67750865-6070-51ad-8963-da3f9cf07671', 'Slovenia Corporate Governance Code', 'Corporate Governance Code, 2004', 'The Code encorporates Slovene legislation, principles of business ethics and the internal Articles of the three institutions. The purpose of the Code is to specify corporate governance standards in Slovenia. The Code''s provisions define more precisely the statutory provisions, present recommended standards for good and responsible governance of Slovene public joint-stock companies and summarize the regulations in force in order to make it easily accessible to both foreign and domestic investors. Primarily, the Code is addressed to public joint-stock companies.', 'The Code encorporates Slovene legislation, principles of business ethics and the internal Articles of the three institutions. The purpose of the Code is to specify corporate governance standards in Slovenia. The Code''s provisions define more precisely the statutory provisions, present recommended standards for good and responsible governance of Slovene public joint-stock companies and summarize the regulations in force in order to make it easily accessible to both foreign and domestic investors. Primarily, the Code is addressed to public joint-stock companies.', 'The Code encorporates Slovene legislation, principles of business ethics and the internal Articles of the three institutions. The purpose of the Code is to specify corporate governance standards in Slovenia. The Code''s provisions define more precisely the statutory provisions, present recommended standards for good and responsible governance of Slovene public joint-stock companies and summarize the regulations in force in order to make it easily accessible to both foreign and domestic investors. Primarily, the Code is addressed to public joint-stock companies.', 'Slovenia', 'governance', 'in_force', '2004-01-01'::date, 'Slovenia', 'https://www.carrotsandsticks.org/policies/163_3', ARRAY['regulations', 'slovenia', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1fd411b1-8b7c-5969-b091-5c2447ca0886', 'South Africa Climate Change Act', 'Climate Change Act', 'The Climate Change Act, 2024, is a comprehensive framework to address climate change in South Africa. It aims to develop an effective national climate change response, facilitate a just transition to a low-carbon and climate-resilient economy, and ensure sustainable development. The Act underscores South Africa''s commitment to international climate agreements such as the Paris Agreement and outlines mitigation and adaptation measures to reduce greenhouse gas emissions and enhance resilience to climate impacts.', 'The Climate Change Act, 2024, is a comprehensive framework to address climate change in South Africa. It aims to develop an effective national climate change response, facilitate a just transition to a low-carbon and climate-resilient economy, and ensure sustainable development. The Act underscores South Africa''s commitment to international climate agreements such as the Paris Agreement and outlines mitigation and adaptation measures to reduce greenhouse gas emissions and enhance resilience to climate impacts.', 'The Climate Change Act, 2024, is a comprehensive framework to address climate change in South Africa. It aims to develop an effective national climate change response, facilitate a just transition to a low-carbon and climate-resilient economy, and ensure sustainable development. The Act underscores South Africa''s commitment to international climate agreements such as the Paris Agreement and outlines mitigation and adaptation measures to reduce greenhouse gas emissions and enhance resilience to climate impacts.', 'South Africa', 'climate', 'in_force', '2024-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_2', ARRAY['sdg2', 'sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'disclosure', 'south africa', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1585bc8d-42c9-51b8-9d5c-2440b29fccde', 'South Africa Green Finance Taxonomy Version 1', 'South Africa Green Finance Taxonomy Version 1, 2022', 'This document sets out the results of the work to date in developing the 1st Edition of the South African Green Finance Taxonomy for environmentally sustainable economic activities.', 'This document sets out the results of the work to date in developing the 1st Edition of the South African Green Finance Taxonomy for environmentally sustainable economic activities.', 'This document sets out the results of the work to date in developing the 1st Edition of the South African Green Finance Taxonomy for environmentally sustainable economic activities.', 'South Africa', 'climate', 'in_force', '2022-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_39', ARRAY['sdg13', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg12', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5edc6aa3-8f44-568e-9b24-5ea65c0d2278', 'South Africa Leading the way for a better tomorrow', 'Leading the way for a better tomorrow. JSE Sustainability Disclosure Guidance, June 2022', 'While the JSE has implicitly held requirements for sustainability disclosure through its links to the King Codes on corporate governance, there has been no prior detailed guidance to assist listed companies on sustainability/ESG reporting. This document provides that support and lays out the wide range of benefits to sustainability disclosure guidance. It recognises the need for clear guidance that achieves the following: 1. To help local companies to navigate the rapidly changing ESG landscape; 2. To acknowledge and reflect South Africa’s unique sustainability challenges; 3. To assist in driving improved ESG performance, accountability, and business leadership; and 4. To contribute to enhanced transparency and consistency. In response to the rapidly evolving landscape of sustainability standards and frameworks, this guidance provides JSE-listed issuers with guidelines specifically tailored to the South African context, while being fully cognisant of global best practice. This Disclosure Guidance will serve as a foundation for further, topic specific guidance. The first of these sub-topics is Climate Disclosure, which will be released alongside this document.', 'While the JSE has implicitly held requirements for sustainability disclosure through its links to the King Codes on corporate governance, there has been no prior detailed guidance to assist listed companies on sustainability/ESG reporting. This document provides that support and lays out the wide range of benefits to sustainability disclosure guidance. It recognises the need for clear guidance that achieves the following: 1. To help local companies to navigate the rapidly changing ESG landscape; 2. To acknowledge and reflect South Africa’s unique sustainability challenges; 3. To assist in driving improved ESG performance, accountability, and business leadership; and 4. To contribute to enhanced transparency and consistency. In response to the rapidly evolving landscape of sustainability standards and frameworks, this guidance provides JSE-listed issuers with guidelines specifically tailored to the South African context, while being fully cognisant of global best practice. This Disclosure Guidance will serve as a foundation for further, topic specific guidance. The first of these sub-topics is Climate Disclosure, which will be released alongside this document.', 'While the JSE has implicitly held requirements for sustainability disclosure through its links to the King Codes on corporate governance, there has been no prior detailed guidance to assist listed companies on sustainability/ESG reporting. This document provides that support and lays out the wide range of benefits to sustainability disclosure guidance. It recognises the need for clear guidance that achieves the following: 1. To help local companies to navigate the rapidly changing ESG landscape; 2. To acknowledge and reflect South Africa’s unique sustainability challenges; 3. To assist in driving improved ESG performance, accountability, and business leadership; and 4. To contribute to enhanced transparency and consistency. In response to the rapidly evolving landscape of sustainability standards and frameworks, this guidance provides JSE-listed issuers with guidelines specifically tailored to the South African context, while being fully cognisant of global best practice. This Disclosure Guidance will serve as a foundation for further, topic specific guidance. The first of these sub-topics is Climate Disclosure, which will be released alongside this document.', 'South Africa', 'climate', 'in_force', '2021-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_38', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'sdg16', 'disclosure', 'south africa', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f02741f2-cdcf-5127-ade7-54a53107c8dd', 'South Africa Financing a Sustainable Economy', 'Financing a Sustainable Economy', 'This paper sets out the research and resultant recommendations of a process to establish minimum practice and standards with regard to climate change and emerging environmental and social risks. It looks at the approach of international financial regulators and the work of local financial institutions.', 'This paper sets out the research and resultant recommendations of a process to establish minimum practice and standards with regard to climate change and emerging environmental and social risks. It looks at the approach of international financial regulators and the work of local financial institutions.', 'This paper sets out the research and resultant recommendations of a process to establish minimum practice and standards with regard to climate change and emerging environmental and social risks. It looks at the approach of international financial regulators and the work of local financial institutions.', 'South Africa', 'climate', 'in_force', '2020-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_25', ARRAY['sdg13', 'sdg14', 'regulations', 'mandatory', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5aeeb49c-0e6f-50fa-b897-615abe43bb25', 'South Africa Life Cycle Management Tools and Guideline for', 'Life Cycle Management Tools and Guideline for the Manufacturing Industry in South Africa', 'This industry guideline demonstrates the strategic value that can be gained in the business sector, as a result of adopting a Life Cycle Management (LCM) approach and includes South African business case studies that have adopted and implemented elements of LCM.', 'This industry guideline demonstrates the strategic value that can be gained in the business sector, as a result of adopting a Life Cycle Management (LCM) approach and includes South African business case studies that have adopted and implemented elements of LCM.', 'This industry guideline demonstrates the strategic value that can be gained in the business sector, as a result of adopting a Life Cycle Management (LCM) approach and includes South African business case studies that have adopted and implemented elements of LCM.', 'South Africa', 'circularity', 'in_force', '2020-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_27', ARRAY['other sustainability policy', 'regulations', 'sdg12', 'south africa', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('be7d3ba2-7939-50b9-934c-234cc655e8ed', 'South Africa''s Low Emission Development Strategy', 'South Africa''s Low Emission Development Strategy 2050', 'This document has been prepared in response to that Article, and presents South Africa''s first Low Emission Development Strategy (SA-LEDS). Through submitting this document to the UNFCCC our country reiterates its commitment to achieving the Paris goals. Implementation of the Strategy will also contribute directly and indirectly to the meeting of Sustainable Development Goals (SDGs). SA-LEDS builds upon years of work on climate change in the country, which has contributed to the establishment of an important set of policy documents. Building on existing plans offers numerous benefits, such as optimizing.', 'This document has been prepared in response to that Article, and presents South Africa''s first Low Emission Development Strategy (SA-LEDS). Through submitting this document to the UNFCCC our country reiterates its commitment to achieving the Paris goals. Implementation of the Strategy will also contribute directly and indirectly to the meeting of Sustainable Development Goals (SDGs). SA-LEDS builds upon years of work on climate change in the country, which has contributed to the establishment of an important set of policy documents. Building on existing plans offers numerous benefits, such as optimizing.', 'This document has been prepared in response to that Article, and presents South Africa''s first Low Emission Development Strategy (SA-LEDS). Through submitting this document to the UNFCCC our country reiterates its commitment to achieving the Paris goals. Implementation of the Strategy will also contribute directly and indirectly to the meeting of Sustainable Development Goals (SDGs). SA-LEDS builds upon years of work on climate change in the country, which has contributed to the establishment of an important set of policy documents. Building on existing plans offers numerous benefits, such as optimizing.', 'South Africa', 'climate', 'in_force', '2020-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_29', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('312065c6-5dfd-51e2-8522-015b3b5b926f', 'South Africa Guidance Notice 1 of 2019 (PFA)', 'Guidance Notice 1 of 2019 (PFA)', 'This purpose of this Guidance Notice is to provide guidance to boards of funds on how the board must comply with Regulation 28(2)(b) read with Regulation 28(2XcXix), in particular how its investment philosophy and objectives, as reflected in its investment policy statement, seeks to ensure the sustainability of its investments and assets, and to set out the Authority''s expectations regarding disclosure and reporting on issues of sustainability.', 'This purpose of this Guidance Notice is to provide guidance to boards of funds on how the board must comply with Regulation 28(2)(b) read with Regulation 28(2XcXix), in particular how its investment philosophy and objectives, as reflected in its investment policy statement, seeks to ensure the sustainability of its investments and assets, and to set out the Authority''s expectations regarding disclosure and reporting on issues of sustainability.', 'This purpose of this Guidance Notice is to provide guidance to boards of funds on how the board must comply with Regulation 28(2)(b) read with Regulation 28(2XcXix), in particular how its investment philosophy and objectives, as reflected in its investment policy statement, seeks to ensure the sustainability of its investments and assets, and to set out the Authority''s expectations regarding disclosure and reporting on issues of sustainability.', 'South Africa', 'climate', 'in_force', '2019-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_12', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b7fb8329-46bf-5eaf-ab21-21c1aae508f6', 'South Africa FSCA Communication 1 of 2019 (PFA): Guidance', 'FSCA Communication 1 of 2019 (PFA): Guidance Notice: Sustainability of investments and assets in the context of a retirement fund’s investment policy statement', 'The purpose of this Communication is to inform stakeholders that a Guidance Notice relating to sustainability of investments and assets in the context of a retirement fund’s investment policy statement (the GN) has been published on the website of the Financial Sector Conduct Authority (FSCA).', 'The purpose of this Communication is to inform stakeholders that a Guidance Notice relating to sustainability of investments and assets in the context of a retirement fund’s investment policy statement (the GN) has been published on the website of the Financial Sector Conduct Authority (FSCA).', 'The purpose of this Communication is to inform stakeholders that a Guidance Notice relating to sustainability of investments and assets in the context of a retirement fund’s investment policy statement (the GN) has been published on the website of the Financial Sector Conduct Authority (FSCA).', 'South Africa', 'climate', 'in_force', '2019-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_28', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5287b728-f14e-5159-ae55-6117e947728d', 'South Africa National Environmental Management: Air Quality Act: Regulations', 'National Environmental Management: Air Quality Act: Regulations: National Greenhouse Gas Emission Reporting', 'This document outlines the updated Air Quality Act of South Africa.', 'This document outlines the updated Air Quality Act of South Africa.', 'This document outlines the updated Air Quality Act of South Africa.', 'South Africa', 'climate', 'in_force', '2017-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_14', ARRAY['sdg13', 'regulations', 'mandatory', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bd450c6d-1616-5c2b-a37d-3a3a60f7d7fe', 'South Africa Governance in SMEs: A Guide to the', 'Governance in SMEs: A Guide to the Application of Corporate Governance in Small and Medium Enterprises', 'In South Africa, King III is the recognised code of governance. It consists of principles (i.e. the underlying outcome to be achieved) and recommendations (i.e. proposed practices to achieve the principles). The governance principles contained in King III apply to all Organisations irrespective of the nature and size of the business. However, the extent to which the recommended practices apply to a specific business will differ from entity to entity.', 'In South Africa, King III is the recognised code of governance. It consists of principles (i.e. the underlying outcome to be achieved) and recommendations (i.e. proposed practices to achieve the principles). The governance principles contained in King III apply to all Organisations irrespective of the nature and size of the business. However, the extent to which the recommended practices apply to a specific business will differ from entity to entity.', 'In South Africa, King III is the recognised code of governance. It consists of principles (i.e. the underlying outcome to be achieved) and recommendations (i.e. proposed practices to achieve the principles). The governance principles contained in King III apply to all Organisations irrespective of the nature and size of the business. However, the extent to which the recommended practices apply to a specific business will differ from entity to entity.', 'South Africa', 'nature', 'in_force', '2017-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_16', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'south africa', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('99c2d2cb-e36d-529b-a582-17f17eb268b2', 'South Africa Johannesburg Stock Exchange (JSE) Listings Requirements', 'Johannesburg Stock Exchange (JSE) Listings Requirements', 'The JSE Listings Requirements provide a regulatory framework for companies seeking to list securities on the Johannesburg Stock Exchange (JSE) and for those already listed. These requirements are designed to ensure transparency, investor protection, and the orderly functioning of the exchange. The framework governs new applications for listing, ongoing obligations, and corporate actions of listed entities. It incorporates principles of corporate governance, disclosure, and fair treatment of investors, aligned with the Financial Markets Act (FMA) and international best practices.', 'The JSE Listings Requirements provide a regulatory framework for companies seeking to list securities on the Johannesburg Stock Exchange (JSE) and for those already listed. These requirements are designed to ensure transparency, investor protection, and the orderly functioning of the exchange. The framework governs new applications for listing, ongoing obligations, and corporate actions of listed entities. It incorporates principles of corporate governance, disclosure, and fair treatment of investors, aligned with the Financial Markets Act (FMA) and international best practices.', 'The JSE Listings Requirements provide a regulatory framework for companies seeking to list securities on the Johannesburg Stock Exchange (JSE) and for those already listed. These requirements are designed to ensure transparency, investor protection, and the orderly functioning of the exchange. The framework governs new applications for listing, ongoing obligations, and corporate actions of listed entities. It incorporates principles of corporate governance, disclosure, and fair treatment of investors, aligned with the Financial Markets Act (FMA) and international best practices.', 'South Africa', 'climate', 'in_force', '2017-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_3', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f0e5b7f2-7eac-530e-b379-7add64e75bbb', 'South Africa JSE Listing Requirement', 'JSE Listing Requirement (2010)', 'An integrated report gives users an all-round view of a company by including social, environmental and economic performance along with the company''s financial performance.', 'An integrated report gives users an all-round view of a company by including social, environmental and economic performance along with the company''s financial performance.', 'An integrated report gives users an all-round view of a company by including social, environmental and economic performance along with the company''s financial performance.', 'South Africa', 'climate', 'in_force', '2017-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_9', ARRAY['south africa', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2961e8dd-be5b-548e-b44b-406d21caf421', 'South Africa Guidelines to listing on the JSE', 'Guidelines to listing on the JSE, 2016', 'This document outlines the Guidelines to Listing on the JSE.', 'This document outlines the Guidelines to Listing on the JSE.', 'This document outlines the Guidelines to Listing on the JSE.', 'South Africa', 'governance', 'in_force', '2016-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_17', ARRAY['south africa', 'guidance_frameworks', 'voluntary', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1febd2d1-f9fe-590f-9fb3-a158fc9770da', 'South Africa King IV Report on Corporate Governance', 'King IV Report on Corporate Governance', 'The King IV Report on Corporate Governance for South Africa, 2016, builds on its predecessors (King I, II, and III) and provides a comprehensive framework for ethical and effective leadership, corporate citizenship, and sustainability. It introduces an outcomes-based approach to governance, emphasizing four key outcomes: ethical culture, good performance, effective control, and legitimacy. The report also shifts from "apply or explain" to "apply and explain," requiring organizations to provide meaningful insights into how they achieve governance principles.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('41381924-35ae-5caf-866f-e788111b375c', 'South Africa National Environmental Management Act: Regulations: Environmental Impact', 'National Environmental Management Act: Regulations: Environmental Impact Assessment: Amendments', 'The purpose of these Regulations is to regulate the procedure and criterias contemplated in Chapter 5 of the Act relating to the preparation, evaluation, submision, procesing and consideration of, and decision on, aplications for environmental authorisations for the comencement of activities, subjected to environmental impact asesment, in order to avoid or mitigate detrimental impacts on the environment, and to ptimise positive nvironmental impacts, and for maters pertaining thereto.', 'The purpose of these Regulations is to regulate the procedure and criterias contemplated in Chapter 5 of the Act relating to the preparation, evaluation, submision, procesing and consideration of, and decision on, aplications for environmental authorisations for the comencement of activities, subjected to environmental impact asesment, in order to avoid or mitigate detrimental impacts on the environment, and to ptimise positive nvironmental impacts, and for maters pertaining thereto.', 'The purpose of these Regulations is to regulate the procedure and criterias contemplated in Chapter 5 of the Act relating to the preparation, evaluation, submision, procesing and consideration of, and decision on, aplications for environmental authorisations for the comencement of activities, subjected to environmental impact asesment, in order to avoid or mitigate detrimental impacts on the environment, and to ptimise positive nvironmental impacts, and for maters pertaining thereto.', 'South Africa', 'governance', 'in_force', '2014-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_35', ARRAY['south africa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
