INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('43846249-f6e2-50c6-93ef-f83a7d589ae0', 'South Africa Mineral and Petroleum Resources Development Amendment Bill', 'Mineral and Petroleum Resources Development Amendment Bill B15D-2013', 'This is a bill to amend the Mineral and Petroleum Resources Development Act, 2002, as amended by the Mineral and Petroleum Resources Development Act, 2008 (Act No. 49 of 2008); so as to remove ambiguities that exist within the Act; to provide for the regulation of associated minerals, partitioning of rights and enhance provisions relating to beneficiation of minerals; to promote national energy security; to streamline administrative processes; to align the Mineral and Petroleum Resources Development Act with the Geoscience Act, 1993 (Act No. 100 of 1993), as amended by the Geoscience Amendment Act, 2010 (Act No. 16 of 2010); to provide for enhanced sanctions; to improve the regulatory system; and to provide for matters connected therewith.', 'This is a bill to amend the Mineral and Petroleum Resources Development Act, 2002, as amended by the Mineral and Petroleum Resources Development Act, 2008 (Act No. 49 of 2008); so as to remove ambiguities that exist within the Act; to provide for the regulation of associated minerals, partitioning of rights and enhance provisions relating to beneficiation of minerals; to promote national energy security; to streamline administrative processes; to align the Mineral and Petroleum Resources Development Act with the Geoscience Act, 1993 (Act No. 100 of 1993), as amended by the Geoscience Amendment Act, 2010 (Act No. 16 of 2010); to provide for enhanced sanctions; to improve the regulatory system; and to provide for matters connected therewith.', 'This is a bill to amend the Mineral and Petroleum Resources Development Act, 2002, as amended by the Mineral and Petroleum Resources Development Act, 2008 (Act No. 49 of 2008); so as to remove ambiguities that exist within the Act; to provide for the regulation of associated minerals, partitioning of rights and enhance provisions relating to beneficiation of minerals; to promote national energy security; to streamline administrative processes; to align the Mineral and Petroleum Resources Development Act with the Geoscience Act, 1993 (Act No. 100 of 1993), as amended by the Geoscience Amendment Act, 2010 (Act No. 16 of 2010); to provide for enhanced sanctions; to improve the regulatory system; and to provide for matters connected therewith.', 'South Africa', 'climate', 'in_force', '2013-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_13', ARRAY['regulations', 'sdg7', 'mandatory', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
