INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d08ca89b-12c6-5cca-986d-727b1e4638b9', 'South Africa Pension Funds Act, 1956: Amendment of Regulation', 'Pension Funds Act, 1956: Amendment of Regulation 28 of the Regulations Made Under Section 36', 'This document amends Regulation 28 of the Regulations made under section 36 of the Pension Funds Act and published under Government Notice No. R.98 in Government Gazette 162 of 26 January 1962.', 'This document amends Regulation 28 of the Regulations made under section 36 of the Pension Funds Act and published under Government Notice No. R.98 in Government Gazette 162 of 26 January 1962.', 'This document amends Regulation 28 of the Regulations made under section 36 of the Pension Funds Act and published under Government Notice No. R.98 in Government Gazette 162 of 26 January 1962.', 'South Africa', 'governance', 'in_force', '2011-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_11', ARRAY['south africa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7e1bf0ee-6712-553d-9fdd-8f5f7a71817f', 'Responsible Investing in South Africa (CRISA)', 'Code for Responsible Investing in South Africa (CRISA)', 'A non-mandatory market-based code of governance, such as the King Code, is (in the context of listed companies) stronger if its implementation is overseen by those with a vested interest in effective market forces i.e. the institutional investor.The institutional investor has by virtue of its share ownership and rights, including voting rights, the ability to in uence and encourage investee companies to apply sound governance principles and practices. Recent experience in South Africa and internationally indicates that market failures in relation to governance are, at least in part, due to an absence of active institutional investors, or investment behaviour driven by short-term results. In reaction to comments on the King Report which were submitted by the South African PRI network and which called for guidance to the investor community to be included in the Report, the King Committee recommended that a separate code be drafted to speci cally set out the expectations from institutional investors in this regard. The Committee on Responsible Investing by Institutional Investors in South Africa has been convened by the IoDSA to develop such a code.', 'A non-mandatory market-based code of governance, such as the King Code, is (in the context of listed companies) stronger if its implementation is overseen by those with a vested interest in effective market forces i.e. the institutional investor.The institutional investor has by virtue of its share ownership and rights, including voting rights, the ability to in uence and encourage investee companies to apply sound governance principles and practices. Recent experience in South Africa and internationally indicates that market failures in relation to governance are, at least in part, due to an absence of active institutional investors, or investment behaviour driven by short-term results. In reaction to comments on the King Report which were submitted by the South African PRI network and which called for guidance to the investor community to be included in the Report, the King Committee recommended that a separate code be drafted to speci cally set out the expectations from institutional investors in this regard. The Committee on Responsible Investing by Institutional Investors in South Africa has been convened by the IoDSA to develop such a code.', 'A non-mandatory market-based code of governance, such as the King Code, is (in the context of listed companies) stronger if its implementation is overseen by those with a vested interest in effective market forces i.e. the institutional investor.The institutional investor has by virtue of its share ownership and rights, including voting rights, the ability to in uence and encourage investee companies to apply sound governance principles and practices. Recent experience in South Africa and internationally indicates that market failures in relation to governance are, at least in part, due to an absence of active institutional investors, or investment behaviour driven by short-term results. In reaction to comments on the King Report which were submitted by the South African PRI network and which called for guidance to the investor community to be included in the Report, the King Committee recommended that a separate code be drafted to speci cally set out the expectations from institutional investors in this regard. The Committee on Responsible Investing by Institutional Investors in South Africa has been convened by the IoDSA to develop such a code.', 'South Africa', 'climate', 'in_force', '2011-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_15', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'sdg16', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3cdbe3c8-94a2-52e5-859c-1bc00943efe4', 'South Africa Explanatory Memorandum on the Draft Regulation 28', 'Explanatory Memorandum on the Draft Regulation 28 That Gives Effect to Section 36(1)(Bb) of the Pension Funds Act 1956, 2010', 'The draft Regulation 28 gives effect to Section 36(1)(bB) of the Pension Funds Act 1956, which provides that the Minister of Finance may make regulations limiting the amount and the extent to which a pension fund may invest in particular assets or in particular kinds or categories of assets, prescribing the basis on which the limit shall be determined and defining the kinds or categories of assets to which the limit applies.', 'The draft Regulation 28 gives effect to Section 36(1)(bB) of the Pension Funds Act 1956, which provides that the Minister of Finance may make regulations limiting the amount and the extent to which a pension fund may invest in particular assets or in particular kinds or categories of assets, prescribing the basis on which the limit shall be determined and defining the kinds or categories of assets to which the limit applies.', 'The draft Regulation 28 gives effect to Section 36(1)(bB) of the Pension Funds Act 1956, which provides that the Minister of Finance may make regulations limiting the amount and the extent to which a pension fund may invest in particular assets or in particular kinds or categories of assets, prescribing the basis on which the limit shall be determined and defining the kinds or categories of assets to which the limit applies.', 'South Africa', 'governance', 'in_force', '2010-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_19', ARRAY['south africa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4e702eed-c2a6-56fc-92a7-a87b586cfdb2', 'South Africa Draft Code for Responsible Investing by Institutional', 'Draft Code for Responsible Investing by Institutional Investors in South Africa', 'The purpose of this Code is, together with the applicable governance standard such as King III, to provide a voluntary framework that can be used to ensure that sound governance is practised. The framework relates to the governance role of boards of companies, institutional shareholders and the ultimate beneficiaries.', 'The purpose of this Code is, together with the applicable governance standard such as King III, to provide a voluntary framework that can be used to ensure that sound governance is practised. The framework relates to the governance role of boards of companies, institutional shareholders and the ultimate beneficiaries.', 'The purpose of this Code is, together with the applicable governance standard such as King III, to provide a voluntary framework that can be used to ensure that sound governance is practised. The framework relates to the governance role of boards of companies, institutional shareholders and the ultimate beneficiaries.', 'South Africa', 'governance', 'in_force', '2010-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_20', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ec559472-b790-51cc-8b2b-4fb37b62fad7', 'King Report on Governance for South Africa', 'King Report on Governance for South Africa 2009', 'The release of King III report on 1 September 2009 represents a significant milestone in the evolution of corporate governance in South Africa and brings with it significant opportunities for organisations that embrace its principles.', 'The release of King III report on 1 September 2009 represents a significant milestone in the evolution of corporate governance in South Africa and brings with it significant opportunities for organisations that embrace its principles.', 'The release of King III report on 1 September 2009 represents a significant milestone in the evolution of corporate governance in South Africa and brings with it significant opportunities for organisations that embrace its principles.', 'South Africa', 'climate', 'in_force', '2009-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_10', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1d00c909-99e1-5414-aa06-52745f07eb0b', 'South Africa National Environmental Management: Waste Act 59 of', 'National Environmental Management: Waste Act 59 of 2008', 'This Waste Act 59 of 2008 aims to reform the law regulating waste management in order to protect health and the environment by providing reasonable measures for the prevention of pollution and ecological degradation and for securing ecologically sustainable development; to provide for institutional arrangements and planning matters; to provide for national norms and standards for regulating the management of waste by all spheres of government; to provide for specific waste management measures; to provide for the licensing and control of waste management activities; to provide for the remediation of contaminated land; to provide for the national waste information system; to provide for compliance and enforcement; and to provide for matters connected therewith.', 'This Waste Act 59 of 2008 aims to reform the law regulating waste management in order to protect health and the environment by providing reasonable measures for the prevention of pollution and ecological degradation and for securing ecologically sustainable development; to provide for institutional arrangements and planning matters; to provide for national norms and standards for regulating the management of waste by all spheres of government; to provide for specific waste management measures; to provide for the licensing and control of waste management activities; to provide for the remediation of contaminated land; to provide for the national waste information system; to provide for compliance and enforcement; and to provide for matters connected therewith.', 'This Waste Act 59 of 2008 aims to reform the law regulating waste management in order to protect health and the environment by providing reasonable measures for the prevention of pollution and ecological degradation and for securing ecologically sustainable development; to provide for institutional arrangements and planning matters; to provide for national norms and standards for regulating the management of waste by all spheres of government; to provide for specific waste management measures; to provide for the licensing and control of waste management activities; to provide for the remediation of contaminated land; to provide for the national waste information system; to provide for compliance and enforcement; and to provide for matters connected therewith.', 'South Africa', 'nature', 'in_force', '2009-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_33', ARRAY['regulations', 'mandatory', 'sdg12', 'disclosure', 'south africa', 'sdg15', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c9277a59-b97f-552a-ac2f-635bc75c0a21', 'South Africa Companies Act 71 of', 'Companies Act 71 of 2008', 'The Companies Act 71 of 2008 aims: to provide for the incorporation, registration, organisation and management of companies, the capitalisation of profit companies, and the registration of offices of foreign companies carrying on business within the Republic; to define the relationships between companies and their respective shareholders or members and directors; to provide for equitable and efficient amalgamations, mergers and takeovers of companies; to provide for efficient rescue of financially distressed companies; to provide appropriate legal redress for investors and third parties with respect to companies; to establish a Companies and Intellectual Property Commission and a Takeover Regulation Panel to administer the requirements of the Act with respect to companies, to establish a Companies Tribunal to facilitate alternative dispute resolution and to review decisions of the Commission; to establish a Financial Reporting Standards Council to advise on requirements for financial record-keeping and reporting by companies; to repeal the Companies Act, 1973 (Act No. 61 of 1973), and make amendments to the Close Corporations Act, 1984 (Act No. 69 of 1984), as necessary to provide for a consistent and harmonious regime of business incorporation and regulation; and to provide for matters connected therewith.', 'The Companies Act 71 of 2008 aims: to provide for the incorporation, registration, organisation and management of companies, the capitalisation of profit companies, and the registration of offices of foreign companies carrying on business within the Republic; to define the relationships between companies and their respective shareholders or members and directors; to provide for equitable and efficient amalgamations, mergers and takeovers of companies; to provide for efficient rescue of financially distressed companies; to provide appropriate legal redress for investors and third parties with respect to companies; to establish a Companies and Intellectual Property Commission and a Takeover Regulation Panel to administer the requirements of the Act with respect to companies, to establish a Companies Tribunal to facilitate alternative dispute resolution and to review decisions of the Commission; to establish a Financial Reporting Standards Council to advise on requirements for financial record-keeping and reporting by companies; to repeal the Companies Act, 1973 (Act No. 61 of 1973), and make amendments to the Close Corporations Act, 1984 (Act No. 69 of 1984), as necessary to provide for a consistent and harmonious regime of business incorporation and regulation; and to provide for matters connected therewith.', 'The Companies Act 71 of 2008 aims: to provide for the incorporation, registration, organisation and management of companies, the capitalisation of profit companies, and the registration of offices of foreign companies carrying on business within the Republic; to define the relationships between companies and their respective shareholders or members and directors; to provide for equitable and efficient amalgamations, mergers and takeovers of companies; to provide for efficient rescue of financially distressed companies; to provide appropriate legal redress for investors and third parties with respect to companies; to establish a Companies and Intellectual Property Commission and a Takeover Regulation Panel to administer the requirements of the Act with respect to companies, to establish a Companies Tribunal to facilitate alternative dispute resolution and to review decisions of the Commission; to establish a Financial Reporting Standards Council to advise on requirements for financial record-keeping and reporting by companies; to repeal the Companies Act, 1973 (Act No. 61 of 1973), and make amendments to the Close Corporations Act, 1984 (Act No. 69 of 1984), as necessary to provide for a consistent and harmonious regime of business incorporation and regulation; and to provide for matters connected therewith.', 'South Africa', 'climate', 'in_force', '2009-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_5', ARRAY['south africa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('61588d6e-00e9-5f0f-96d8-390d151cc023', 'South Africa Consumer Protection Act 68 of', 'Consumer Protection Act 68 of 2008', 'The Consumer Protection Act 68 of 2008 aims: to promote a fair, accessible and sustainable marketplace for consumer products and services and for that purpose to establish national norms and standards relating to consumer protection; to provide for improved standards of consumer information; to prohibit certain unfair marketing and business practices; to promote responsible consumer behaviour; to promote a consistent legislative and enforcement framework relating to consumer transactions and agreements.', 'The Consumer Protection Act 68 of 2008 aims: to promote a fair, accessible and sustainable marketplace for consumer products and services and for that purpose to establish national norms and standards relating to consumer protection; to provide for improved standards of consumer information; to prohibit certain unfair marketing and business practices; to promote responsible consumer behaviour; to promote a consistent legislative and enforcement framework relating to consumer transactions and agreements.', 'The Consumer Protection Act 68 of 2008 aims: to promote a fair, accessible and sustainable marketplace for consumer products and services and for that purpose to establish national norms and standards relating to consumer protection; to provide for improved standards of consumer information; to prohibit certain unfair marketing and business practices; to promote responsible consumer behaviour; to promote a consistent legislative and enforcement framework relating to consumer transactions and agreements.', 'South Africa', 'climate', 'in_force', '2008-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_4', ARRAY['sdg13', 'regulations', 'mandatory', 