INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9a8efefc-cf49-50f1-a706-5e18304349a4', 'South Africa Circular PF - Good Governance of Retirement', 'Circular PF No. 130 - Good Governance of Retirement Funds', 'This document is a circular on the good governance of retirement funds, published by the Financial services board of South Africa.', 'This document is a circular on the good governance of retirement funds, published by the Financial services board of South Africa.', 'This document is a circular on the good governance of retirement funds, published by the Financial services board of South Africa.', 'South Africa', 'governance', 'in_force', '2007-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_24', ARRAY['other sustainability policy', 'mandatory', 'sdg16', 'mandatory_regulations', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('edc6bc69-6eba-52da-9308-1c900b56f526', 'South Africa Integrated Environmental Management Information Series. Environmental Impact', 'Integrated Environmental Management Information Series.  Environmental Impact Reporting 2004', 'This document serves as an introductory reference on environmental impact reporting, addressing common issues, improving content quality, and maintaining an "issues trail" from draft to final reports, aimed at informing a diverse audience, from government to academia.', 'This document serves as an introductory reference on environmental impact reporting, addressing common issues, improving content quality, and maintaining an "issues trail" from draft to final reports, aimed at informing a diverse audience, from government to academia.', 'This document serves as an introductory reference on environmental impact reporting, addressing common issues, improving content quality, and maintaining an "issues trail" from draft to final reports, aimed at informing a diverse audience, from government to academia.', 'South Africa', 'climate', 'in_force', '2004-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_40', ARRAY['south africa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dfb2e0e3-ac38-52d3-9701-d4b44cc5efea', 'South Africa Broad-Based Black Economic Empowerment (B-BBEE) Act (Act', 'Broad-Based Black Economic Empowerment (B-BBEE) Act (Act No. 53 of 2003)', 'The Broad-Based Black Economic Empowerment (B-BBEE) Amendment Bill, 2012, enhances the original B-BBEE Act of 2003 to strengthen compliance, enforcement, and alignment with other South African legislation. Key amendments include establishing the B-BBEE Commission to monitor compliance, introducing penalties for non-compliance and fronting practices, and clarifying sector-specific codes of good practice. The Bill promotes access to economic activities and resources for historically disadvantaged groups, particularly Black South Africans, through defined initiatives such as skills development, preferential procurement, and ownership transformation. It also mandates transparent reporting and compliance measures for businesses and public entities.', 'The Broad-Based Black Economic Empowerment (B-BBEE) Amendment Bill, 2012, enhances the original B-BBEE Act of 2003 to strengthen compliance, enforcement, and alignment with other South African legislation. Key amendments include establishing the B-BBEE Commission to monitor compliance, introducing penalties for non-compliance and fronting practices, and clarifying sector-specific codes of good practice. The Bill promotes access to economic activities and resources for historically disadvantaged groups, particularly Black South Africans, through defined initiatives such as skills development, preferential procurement, and ownership transformation. It also mandates transparent reporting and compliance measures for businesses and public entities.', 'The Broad-Based Black Economic Empowerment (B-BBEE) Amendment Bill, 2012, enhances the original B-BBEE Act of 2003 to strengthen compliance, enforcement, and alignment with other South African legislation. Key amendments include establishing the B-BBEE Commission to monitor compliance, introducing penalties for non-compliance and fronting practices, and clarifying sector-specific codes of good practice. The Bill promotes access to economic activities and resources for historically disadvantaged groups, particularly Black South Africans, through defined initiatives such as skills development, preferential procurement, and ownership transformation. It also mandates transparent reporting and compliance measures for businesses and public entities.', 'South Africa', 'climate', 'in_force', '2003-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_26', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg12', 'disclosure', 'south africa', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('43ce9b7e-038e-5bff-847c-c61555461daa', 'South Africa Broad-based Black Economic Empowerment Act 53 of', 'Broad-based Black Economic Empowerment Act 53 of 2003', 'The Broad-based Black Economic Empowerment Act 53 of 2003 intends: to establish a legislative framework for the promotion of black economic empowerment; to empower the Minister to issue codes of good practice and to publish transformation charters; to establish the Black Economic Empowerment Advisory Council; and to provide for matters connected therewith.', 'The Broad-based Black Economic Empowerment Act 53 of 2003 intends: to establish a legislative framework for the promotion of black economic empowerment; to empower the Minister to issue codes of good practice and to publish transformation charters; to establish the Black Economic Empowerment Advisory Council; and to provide for matters connected therewith.', 'The Broad-based Black Economic Empowerment Act 53 of 2003 intends: to establish a legislative framework for the promotion of black economic empowerment; to empower the Minister to issue codes of good practice and to publish transformation charters; to establish the Black Economic Empowerment Advisory Council; and to provide for matters connected therewith.', 'South Africa', 'governance', 'in_force', '2003-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_8', ARRAY['south africa', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1ebcef9b-2cfb-556a-904f-fb5907cb01d6', 'South Africa Mineral and Petroleum Resources Development Act 28', 'Mineral and Petroleum Resources Development Act 28 of 2002', 'The Act aims to make provision for equitable access to and sustainable development of the nation''s mineral and petroleum resources and for related matters. It was amended by the Minerals and Energy Laws Amendment Act 11 of 2005 and the Mineral and Petroleum Resources Development Amendment Act 49 of 2008.', 'The Act aims to make provision for equitable access to and sustainable development of the nation''s mineral and petroleum resources and for related matters. It was amended by the Minerals and Energy Laws Amendment Act 11 of 2005 and the Mineral and Petroleum Resources Development Amendment Act 49 of 2008.', 'The Act aims to make provision for equitable access to and sustainable development of the nation''s mineral and petroleum resources and for related matters. It was amended by the Minerals and Energy Laws Amendment Act 11 of 2005 and the Mineral and Petroleum Resources Development Amendment Act 49 of 2008.', 'South Africa', 'climate', 'in_force', '2002-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_6', ARRAY['regulations', 'sdg7', 'mandatory', 'disclosure', 'south africa']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cc08f8e4-681c-5d64-adbd-d88fb3bd92a7', 'South Africa National Environmental Management Act 107 of 1998', 'National Environmental Management Act 107 of 1998 (as amended)', 'The National Environmental Management Act (NEMA) 107 of 1998 establishes a comprehensive legal framework for cooperative environmental governance in South Africa. It is designed to promote sustainable development, environmental protection, and equitable access to environmental resources. Key objectives include integrating environmental management principles into development activities, ensuring public participation in decision-making, and coordinating governance across national, provincial, and local levels. The Act outlines the roles and responsibilities of various governmental and non-governmental entities, emphasizing accountability and transparency.', 'The National Environmental Management Act (NEMA) 107 of 1998 establishes a comprehensive legal framework for cooperative environmental governance in South Africa. It is designed to promote sustainable development, environmental protection, and equitable access to environmental resources. Key objectives include integrating environmental management principles into development activities, ensuring public participation in decision-making, and coordinating governance across national, provincial, and local levels. The Act outlines the roles and responsibilities of various governmental and non-governmental entities, emphasizing accountability and transparency.', 'The National Environmental Management Act (NEMA) 107 of 1998 establishes a comprehensive legal framework for cooperative environmental governance in South Africa. It is designed to promote sustainable development, environmental protection, and equitable access to environmental resources. Key objectives include integrating environmental management principles into development activities, ensuring public participation in decision-making, and coordinating governance across national, provincial, and local levels. The Act outlines the roles and responsibilities of various governmental and non-governmental entities, emphasizing accountability and transparency.', 'South Africa', 'climate', 'in_force', '1998-01-01'::date, 'South Africa', 'https://www.carrotsandsticks.org/policies/166_1', ARRAY['sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'sdg16', 'south africa', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cc81e44a-4295-5558-a238-f454e04a9e54', 'South Africa Skills Development Act', 'Skills Development Act, 1998', 'The Skills Development Act 97 of 1998 intends: to provide an institutional framework to devise and implement national, sector and workplace strategies to develop and improve the skills of the South African work force; to integrate those strategies within the National Qualifications Framework contemplated in the South African Qualifications Authority Act, 1995; to provide for Iearnerships that lead to recognised occupational qualifications; to provide for the financing of skills development by means of a levy-grant scheme and a National Skills Fund; to provide for and regulate employment services; and 
